import{_ as e,c as r,o as t,b2 as c}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7Cascader 级联选择器","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-cascader.md","filePath":"docs/frontend/components/通用组件/c7-cascader.md"}'),d={name:"docs/frontend/components/通用组件/c7-cascader.md"};function s(a,o,n,g,l,i){return t(),r("div",null,[...o[0]||(o[0]=[c('<h1 id="c7cascader-级联选择器" tabindex="-1">C7Cascader 级联选择器 <a class="header-anchor vp-link" href="#c7cascader-级联选择器" aria-label="Permalink to &quot;C7Cascader 级联选择器&quot;">​</a></h1><p>在 <strong><code>ElCascader</code></strong> 上封装 <strong>静态 / 整树异步 / 懒加载</strong>、<strong><code>fetchData</code> + <code>resultKey</code> + <code>dataFormatter</code></strong>、<strong><code>labelKey</code> / <code>valueKey</code> / <code>childrenKey</code></strong> 映射，以及 <strong><code>multiple</code> + <code>separator</code></strong>、<strong><code>valueType</code></strong>、<strong><code>load-error</code> / <code>loading-change</code></strong>，契约对齐 <strong><code>C7TreeSelect</code></strong> / <strong><code>C7Select</code></strong>。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7Cascader/index.vue</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong>数据</strong><ul><li><strong>静态</strong>：<code>dataList</code> 优先于 <code>options</code>（与树选一致）。</li><li><strong>整树异步</strong>：无静态、<strong>未启用懒加载</strong>、<strong><code>autoLoad=true</code></strong> 时，挂载后 <strong><code>fetchData({ ...fetchParams })</code></strong>（无 <code>parentId</code>）。</li><li><strong>懒加载</strong>：<strong><code>lazy=true</code></strong> 且提供 <strong><code>fetchData</code></strong> 时，通过 EP <strong><code>props.lazy</code> + <code>props.lazyLoad</code></strong> 按层请求 <strong><code>fetchData({ parentId, ...fetchParams })</code></strong>；根层 <strong><code>parentId === rootParentId</code></strong>（默认 <strong><code>null</code></strong>），子层为父节点映射后的 <strong><code>value</code></strong>；接口返回 <strong>当前层扁平子列表</strong>。</li></ul></li><li><strong>解析</strong>：自 <strong><code>response.data</code></strong> 起，<strong><code>resultKey</code></strong>（lodash 点路径）取数组，再经 <strong><code>dataFormatter</code></strong>；<strong><code>resultKey</code> 不表示子节点字段名</strong>，子节点字段为 <strong><code>childrenKey</code></strong>。</li><li><strong>多选 + <code>separator</code></strong>：仅当 <strong><code>emit-path=&quot;false&quot;</code></strong> 且多选值为 <strong>一维标量</strong> 时，对外为 <strong>英文逗号串</strong>（空为 <strong><code>&#39;&#39;</code></strong>）。<strong>Element Plus 默认 <code>emitPath</code> 为 <code>true</code></strong>，此时 <strong><code>separator</code> 无效</strong>，开发环境会 <strong><code>console.warn</code></strong>。</li><li><strong><code>valueType</code></strong>：<code>auto</code> | <code>string</code> | <code>number</code>；<strong><code>emitPath=true</code></strong> 时对路径上 <strong>各层标量</strong> 做类型转换。</li><li><strong>透传</strong>：未占用键通过 attrs 透传至 <strong><code>ElCascader</code></strong>；<strong><code>props</code></strong>（级联面板配置）会与内部的 <strong><code>lazy</code> / <code>lazyLoad</code></strong> 浅合并（启用 C7 懒加载时由组件注入 <strong><code>lazyLoad</code></strong>）。</li><li><strong>事件</strong>：<code>update:modelValue</code>、<code>change</code>、<code>visible-change</code>、<code>load-error</code>、<code>loading-change</code>。</li><li><strong>方法</strong>：<code>reload()</code>（静态时重同步内外值；整树异步重新请求；懒加载通过 <strong>内部 key</strong> 重置面板）。</li></ul><h2 id="与-c7treeselect-的选型-建议" tabindex="-1">与 C7TreeSelect 的选型（建议） <a class="header-anchor vp-link" href="#与-c7treeselect-的选型-建议" aria-label="Permalink to &quot;与 C7TreeSelect 的选型（建议）&quot;">​</a></h2><ul><li><strong>级联多步、层级深、每步选项较少</strong>：优先 <strong>C7Cascader</strong>。</li><li><strong>树内搜索、勾选、复杂节点展示</strong>：优先 <strong>C7TreeSelect</strong>。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p><code>main.js</code> 调用 <code>installPackages(app)</code> 后，可使用 <code>&lt;c7-cascader /&gt;</code> / <code>&lt;C7Cascader /&gt;</code>。</p><h2 id="dev-演示" tabindex="-1">Dev 演示 <a class="header-anchor vp-link" href="#dev-演示" aria-label="Permalink to &quot;Dev 演示&quot;">​</a></h2><p>路由：<code>/dev/c7-cascader-e2e</code>（<code>quick-ui/src/views/dev/C7CascaderE2E.vue</code>）。</p><h2 id="限制" tabindex="-1">限制 <a class="header-anchor vp-link" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li>多选 value 含英文逗号时，<strong>勿</strong>使用 <strong><code>separator</code></strong>。</li><li><strong><code>emitPath=true</code></strong>（含默认）或值为 <strong>路径嵌套数组</strong> 时，<strong>勿</strong>依赖 <strong><code>separator</code></strong> 逗号串。</li></ul><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><ul><li>设计说明：<code>docs/superpowers/specs/2026-05-08-c7-cascader-design.md</code></li><li>OpenSpec：<code>openspec/changes/ui-c7-cascader/specs/ui-c7-cascader/spec.md</code></li></ul>',15)])])}const h=e(d,[["render",s]]);export{u as __pageData,h as default};
